// 列幅の純関数（ドラッグで変えた列幅の保存・復元・差分）。React にも window にも触らない。
//
// 保存形式: { [columnKey]: number(px) } の JSON。**既定から変えた列だけ**を持つ（既定に戻した列は消す）。
// 壊れた JSON・知らない列・数値でない値は黙って捨てる（保存データのせいで画面が壊れないこと）。

export interface ColumnWidthSpec {
  key: string;
  /** 既定の幅(px)。null＝固定幅を持たない伸縮列（残りを取る）。 */
  defaultWidth: number | null;
  /** 最小幅(px)。省略時は COLUMN_WIDTH_DEFAULT_MIN。 */
  minWidth?: number;
  /** false で幅を変えられない列（既定 true）。 */
  resizable?: boolean;
}

/** 列ごとの最小幅の既定値(px)。 */
export const COLUMN_WIDTH_DEFAULT_MIN = 48;
/** 保存値の上限（壊れたデータで巨大な幅にならないための安全弁。操作上の上限ではない）。 */
export const COLUMN_WIDTH_SANITY_MAX = 4000;

export type ColumnWidthOverrides = Record<string, number>;

export function columnMinWidth(spec: Pick<ColumnWidthSpec, 'minWidth'>): number {
  const m = spec.minWidth;
  return typeof m === 'number' && Number.isFinite(m) && m > 0 ? Math.round(m) : COLUMN_WIDTH_DEFAULT_MIN;
}

export function isColumnResizable(spec: ColumnWidthSpec): boolean {
  return spec.resizable !== false;
}

/** 最小幅以上の整数(px)に丸める。数値でなければ最小幅。 */
export function clampColumnWidth(px: number, minWidth: number = COLUMN_WIDTH_DEFAULT_MIN): number {
  if (!Number.isFinite(px)) return minWidth;
  return Math.max(minWidth, Math.round(px));
}

/** 保存文字列を読む。壊れていたら {}。知らない列・幅を変えられない列は捨て、最小幅未満は最小幅へ。 */
export function parseSavedColumnWidths(raw: string | null | undefined, specs: readonly ColumnWidthSpec[]): ColumnWidthOverrides {
  if (!raw) return {};
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return {};
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
  const source = parsed as Record<string, unknown>;
  const out: ColumnWidthOverrides = {};
  for (const spec of specs) {
    if (!isColumnResizable(spec)) continue;
    const v = source[spec.key];
    if (typeof v !== 'number' || !Number.isFinite(v) || v <= 0 || v > COLUMN_WIDTH_SANITY_MAX) continue;
    out[spec.key] = clampColumnWidth(v, columnMinWidth(spec));
  }
  return diffColumnWidthsFromDefaults(out, specs);
}

/** 既定と同じ値・知らない列を落として、変えた列だけにする。 */
export function diffColumnWidthsFromDefaults(widths: Readonly<Record<string, number>>, specs: readonly ColumnWidthSpec[]): ColumnWidthOverrides {
  const out: ColumnWidthOverrides = {};
  for (const spec of specs) {
    const v = widths[spec.key];
    if (typeof v !== 'number' || !Number.isFinite(v)) continue;
    if (spec.defaultWidth !== null && v === spec.defaultWidth) continue;
    out[spec.key] = v;
  }
  return out;
}

export function serializeColumnWidths(overrides: Readonly<Record<string, number>>, specs: readonly ColumnWidthSpec[]): string {
  return JSON.stringify(diffColumnWidthsFromDefaults(overrides, specs));
}

/** 実際に使う幅。変えた列は保存値、それ以外は既定（null＝伸縮）。 */
export function resolveColumnWidths(specs: readonly ColumnWidthSpec[], overrides: Readonly<Record<string, number>>): Record<string, number | null> {
  const out: Record<string, number | null> = {};
  for (const spec of specs) {
    const v = overrides[spec.key];
    out[spec.key] = typeof v === 'number' && isColumnResizable(spec) ? v : spec.defaultWidth;
  }
  return out;
}

/** 1 列ぶんを更新した overrides を返す（最小幅へ丸め、既定と同じなら消す）。知らない列・固定列は据え置き。 */
export function withColumnWidth(
  overrides: Readonly<Record<string, number>>,
  specs: readonly ColumnWidthSpec[],
  key: string,
  px: number,
): ColumnWidthOverrides {
  const spec = specs.find((s) => s.key === key);
  if (!spec || !isColumnResizable(spec)) return { ...overrides };
  return diffColumnWidthsFromDefaults({ ...overrides, [key]: clampColumnWidth(px, columnMinWidth(spec)) }, specs);
}

export function withoutColumnWidth(overrides: Readonly<Record<string, number>>, key: string): ColumnWidthOverrides {
  const { [key]: _removed, ...rest } = overrides;
  return rest;
}
